from flask import Flask, request, render_template_string

app = Flask(__name__)

# Variable to store the URL
url = ""

def route_with_ping(url_path):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            global url
            url = url_path
            # Execute the ping command
            try:
                result = subprocess.run(['ping', '-c', '4', url_path], 
                                        capture_output=True, text=True, timeout=10)
                if result.returncode == 0:
                    ping_output = result.stdout
                else:
                    ping_output = result.stderr
            except subprocess.TimeoutExpired:
                ping_output = "Ping timed out."
            except Exception as e:
                ping_output = f"Error: {e}"

            # Return the URL and ping result
            return render_template_string(f"""
            <h1>Ping Result for {url_path}</h1>
            <p><strong>URL:</strong> {url_path}</p>
            <pre>{ping_output}</pre>
            <p><a href="/">Back to Home</a></p>
            """)
        app.add_url_rule(url_path, func.__name__, wrapper, methods=['GET'])
        return wrapper
    return decorator

# Define the ping function with the decorator
@route_with_ping('/ping')
def ping():
    return "Ping request received."

if __name__ == '__main__':
    app.run(debug=True)

