def ping_decorator(url):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Extract the URL from the request (assuming it's passed as a parameter)
            # Here we assume the URL is passed as a keyword argument named 'url'
            # You can modify this logic based on how you're passing the URL
            requested_url = kwargs.get('url') or args[0] if args else None

            if not requested_url:
                return "No URL provided"

            # Store the URL for later use
            ping_url = requested_url

            # Ping the URL using the system's ping command
            try:
                # Use subprocess to run the ping command
                result = subprocess.run(['ping', '-c', '4', ping_url], 
                                        capture_output=True, text=True, timeout=10)

                if result.returncode == 0:
                    ping_status = "Ping successful"
                else:
