import subprocess
import urllib.parse
from flask import Flask, request, jsonify

app = Flask(__name__)

# URL を保存する変数
url = "https://example.com"

@app.route('/ping', methods=['GET'])
def ping():
    # URL パラメータを取得（クエリパラメータ）
    url_param = request.args.get('url')

    # URL が指定されていない場合
    if not url_param:
        return jsonify({"error": "URL is required"}), 400

    # URL の構文チェック
    try:
        result = urllib.parse.urlparse(url_param)
        if not result.scheme or not result.netloc:
            return jsonify({"error": "Invalid URL format"}), 400
    except Exception:
        return jsonify({"error": "Invalid URL format"}), 400

    # ping コマンドを実行
    try:
        # ping コマンドを実行（Linux/Mac用）
        result = subprocess.run(['ping', '-c', '4', result.netloc], 
                              capture_output=True, text=True, timeout=10)

        if result.returncode == 0:
            return jsonify({"url": url_param, "status": "success", "output": result.stdout})
        else:
            return jsonify({"url": url_param, "status": "failed", "error": result.stderr}), 500
    except subprocess.TimeoutExpired:
        return jsonify({"url": url_param, "status": "timeout", "error": "Ping request timed out"}), 500
    except Exception as e:
        return jsonify({"url": url_param, "status": "error", "error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)

