import subprocess
import re
from functools import wraps

def ping_url(url):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Execute the ping command
            try:
                result = subprocess.run(['ping', '-c', '4', url], capture_output=True, text=True, timeout=10)
                if result.returncode == 0:
                    # Extract the response time from ping output
                    match = re.search(r'time=([\d.]+) ms', result.stdout)
                    response_time = match.group(1) if match else "unknown"
                    # Call the original function with the URL and response time
                    return func(url, response_time)
                else:
                    # If ping fails, return an error message
                    return func(url, "unreachable")
            except subprocess.TimeoutExpired:
                return func(url, "timeout")
            except Exception as e:
                return func(url, f"error: {str(e)}")
        return wrapper
    return decorator

# Example usage:
@ping_url("http://example.com")
def handle_ping_result(url, response_time):
    return f"Ping to {url} completed. Response time: {response_time} ms"

# Test the function
print(handle_ping_result())

